const stone = find_block({ names: ['stone', 'andesite', 'diorite', 'granite'], max_distance: 24 });
if (!stone) {
  return { done: false, detail: 'no stone within 24 blocks' };
}
const dug = await dig(stone.x, stone.y, stone.z);
if (!dug.ok) {
  return { done: false, detail: dug.detail };
}
for (const name of ['cobblestone', 'stone', 'andesite', 'diorite', 'granite']) {
  if (inventory_count(name) > 0) {
    await leave_at_depot(name, 1);
    break;
  }
}
return { done: true, detail: 'mined stone and left it at the depot' };
